    var m = /((?:weekly|daily|monthly|hourly|yearly)(?:\s*\([^)]*\))?)\s+(?:usage\s+)?limit/i.exec(text);
    if (m) return m[1];
    m = /((?:7|14|24|30)-day)\s+(?:usage\s+)?limit/i.exec(text);
    if (m) return m[1];
    m = /(usage\s+limit)\s+((?:weekly|daily|monthly|hourly|yearly)(?:\s*\([^)]*\))?)/i.exec(text);
    if (m) return m[2];
    return null;
}

