    var t = String(text || '');
    if (!t.trim()) return null;
    var has403 = FORBIDDEN_RE.test(t);
    var quotaBody = QUOTA_BODY_RE.test(t);
    var chainExhausted = CHAIN_EXHAUSTED_RE.test(t);
    var window = extractQuotaWindow(t);
