    return 'quota-probe: ' + count;
}

function countProbeMarkers(bodies) {
    var count = 0;
    var re = /^\s*quota-probe:\s*(\d+)\s*$/gm;
    var list = Array.isArray(bodies) ? bodies : [];
    for (var i = 0; i < list.length; i++) {
