function completeInterruptedPath(ticketKey, hasGitChanges, cliTool, config, ticket, tracker, statuses, params, scm, quotaClassification) {
    if (hasGitChanges) {
        console.log('Partial git changes found — pushing to preserve analysis work...');
        try {
