    var cmd = jobParams && jobParams.quotaProbeCommand;
    if (typeof cmd === 'string' && cmd.trim()) return cmd;
    return 'bash -c \'curl --fail -sS -m 30 -o /dev/null -X POST "$FA_PROVIDER_BASE_URL/chat/completions" ' +
