    return maxMarkerNumber(bodies, /^\s*quota-park-tick:\s*(\d+)\s*$/gm);
}

function countProbeMarkers(bodies) {
    return maxMarkerNumber(bodies, /^\s*quota-probe:\s*(\d+)\s*$/gm);
