function runProbeCommand(command) {
    try {
        cli_execute_command({ command: command });
        return { ok: true, detail: null };
    } catch (e) {
        return { ok: false, detail: String((e && e.message) || e).replace(/\s+/g, ' ').trim().substring(0, 200) };
